#include <set>

class stringx {
  char data[8];
public:
  bool operator<(const stringx &) const;
};

template<class T>
struct my_allocator : public allocator<T> {};

typedef _Rb_tree<stringx, stringx, _Identity<stringx>, less<stringx>,
                 my_allocator<stringx> > tree_type;

template pair<tree_type::iterator, bool>
tree_type::insert_unique(const stringx &);
